"""Total values by key and answer queries.

Input file: records ("<key> <value>" lines), one empty line, then query keys.
Keys are compared as raw bytes, so any byte sequence is a valid key.
"""

import sys

INT64_MIN = -(2**63)
INT64_MAX = 2**63 - 1


def parse(data):
    """Split file bytes into (records, queries) line lists."""
    lines = data.split(b"\n")
    records = []
    queries = []
    in_records = True
    for raw in lines:
        line = raw.rstrip(b"\r")
        if in_records:
            if line.strip() == b"":
                in_records = False
                continue
            records.append(line)
        else:
            query = line.strip()
            if query:
                queries.append(query)
    return records, queries


def totals(records):
    """Return {key: (total, overflowed)} accumulated in record order."""
    result = {}
    for line in records:
        parts = line.split()
        if len(parts) != 2:
            continue
        key, value = parts[0], int(parts[1])
        total, overflowed = result.get(key, (0, False))
        if not overflowed:
            total += value
            if total < INT64_MIN or total > INT64_MAX:
                overflowed = True
        result[key] = (total, overflowed)
    return result


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: main.py <file>\n")
        return 2
    with open(argv[1], "rb") as f:
        data = f.read()

    records, queries = parse(data)
    result = totals(records)

    out = sys.stdout.buffer
    for key in queries:
        if key not in result:
            out.write(key + b"=absent\n")
            continue
        total, overflowed = result[key]
        if overflowed:
            out.write(key + b"=overflow\n")
        else:
            out.write(key + b"=" + str(total).encode("ascii") + b"\n")
    out.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

